parameters.jsCode:
const proposalRaw = $('Groq: Generate Proposal Draft').item?.json?.choices?.[0]?.message?.content || '{}';
let proposal = {};
try {
  proposal = JSON.parse(proposalRaw);
} catch(e) {
  const match = proposalRaw.match(/\{[\s\S]*\}/);
  proposal = match ? JSON.parse(match[0]) : { raw_content: proposalRaw };
}

const pptxResp = $input.first()?.json || {};
const prev = $('Process RAG Matrix & Staffing').item.json;

return [{
  json: {
    tender: prev.tender,
    prospect_profile: prev.prospect_profile,
    rag_matching: prev.rag_matching,
    proposal_draft: proposal,
    pptx_deliverable: {
      file_name: pptxResp.file_name || `${prev.tender.id}_OliveSoft_Proposal.pptx`,
      download_url: pptxResp.download_url || `/proposals/${prev.tender.id}/download`,
      total_price_tnd: pptxResp.total_price_tnd || proposal.pricing_estimate_tnd || 145000,
      total_duration_weeks: pptxResp.total_duration_weeks || proposal.timeline_weeks || 16
    },
    dashboard_status: 'READY_FOR_COMMERCIAL_REVIEW',
    delivered_at: new Date().toISOString()
  }
}];
